'use strict';

// MODULES //

var extractStaticHelpers = require( './extract_static_helpers.js' );
var groupContiguousLines = require( './group_contiguous_lines.js' );
var processBlock = require( './process_block.js' );


// MAIN //

/**
* Flushes a collected example block by checking skip conditions and, if not skipped, processing it into a structured object, extracting any required static helpers, and adding it to the output.
*
* @private
* @param {Array<Object>} blockLines - collected lines of the current block
* @param {Array<string>} lines - all source lines
* @param {number} startIdx - line index from which to begin scanning for a skip marker
* @param {Array<Object>} blocks - output array to push processed block into
* @param {string} file - file path
*
* @example
* flushBlock( blockLines, lines, i, blocks, '/path/to/file.c' );
*/
function flushBlock( blockLines, lines, startIdx, blocks, file ) {
	var staticHelpers;
	var scanLine;
	var blockObj;
	var k;
	var j;

	// Find skip rules and stop if a function is reached...
	for ( j = startIdx; j < lines.length; j++ ) {
		scanLine = lines[ j ];
		if ( /\/\/\s*stdlib-c-doctest\s+disable\b/.test( scanLine ) ) {
			return;
		}
		if ( /\{/.test( scanLine ) ) {
			break;
		}
	}

	// Check for ellipsis placeholder in example content...
	for ( k = 0; k < blockLines.length; k++ ) {
		if ( /\.\.\./.test( blockLines[ k ].text ) ) {
			return;
		}
	}

	blockObj = processBlock( blockLines, file, blocks.length );
	staticHelpers = extractStaticHelpers( lines );
	if ( staticHelpers.length > 0 ) {
		blockObj.staticHelpers = groupContiguousLines( staticHelpers );
	}
	blocks.push( blockObj );
}


// EXPORTS //

module.exports = flushBlock;
